import type { ConfigType } from '@plone/registry';

/**
 * Applies the configuration of the app's add-ons, in add-on order, to the
 * registry configuration. Generated by the Plone registry Vite plugin.
 */
export default function applyAddonConfiguration(config: ConfigType): ConfigType;

/** The add-ons of the app, as the registry found them. */
export declare const addonsInfo: Array<Record<string, unknown>>;
